const base=$('Preparar respuesta final').first().json;
const raw=$json.text ?? $json.output ?? $json.response ?? '';
let d={};try{d=JSON.parse(String(raw).replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim());}catch(e){}
const score=Number(d.exactitud_factual);
const valid=Number.isInteger(score)&&score>=1&&score<=5;
const veredicto=valid?(score>=4?'APROBADO':score===3?'CORREGIR':'RECHAZADO'):'RECHAZADO';
const escalar=base.requires_human===true||base.status==='needs_human'||veredicto!=='APROBADO';
return [{json:{...base,judge_score:valid?score:0,judge_veredicto:veredicto,judge_feedback:String(d.feedback??'').slice(0,600),judge_justificacion:String(d.justificacion??'Salida inválida del juez').slice(0,600),requires_human:escalar,status:escalar?'needs_human':base.status,respuesta:escalar?'Tu solicitud fue recibida y requiere revisión de nuestro equipo antes de emitir una respuesta definitiva.':base.respuesta,judge_respuesta_original:base.respuesta,judge_evaluacion_disponible:valid}}];
